<?php
require __DIR__.'/config.php';if(user())go('dashboard.php');$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';
 try{
  $q=db()->prepare("SELECT u.*,e.full_name,r.role_name,e.employee_id FROM users u JOIN employees e ON e.employee_id=u.linked_employee_id JOIN user_roles ur ON ur.user_id=u.user_id JOIN roles r ON r.role_id=ur.role_id WHERE LOWER(e.email)=? AND r.role_name IN ('Administrator','Employee')");$q->execute([$email]);$u=$q->fetch();
  if(!$u){$error='Email or password is incorrect.';db()->prepare("INSERT INTO audit_logs(user_id,action,target_table,description,ip_address,result) VALUES(NULL,'STAFF_LOGIN','users',?,?, 'failure')")->execute(['Unknown staff login: '.$email,$_SERVER['REMOTE_ADDR']??null]);}
  elseif($u['status']!=='active')$error='This login is '.$u['status'].'. Contact an administrator.';
  elseif(!password_verify($pw,$u['password_hash'])){$n=(int)$u['failed_login_attempts']+1;$status=$n>=5?'locked':'active';db()->prepare('UPDATE users SET failed_login_attempts=?,status=? WHERE user_id=?')->execute([$n,$status,$u['user_id']]);db()->prepare("INSERT INTO audit_logs(user_id,action,target_table,target_id,description,ip_address,result) VALUES(?,'STAFF_LOGIN','users',?,?,?,'failure')")->execute([$u['user_id'],$u['user_id'],'Failed login attempt '.$n,$_SERVER['REMOTE_ADDR']??null]);$error=$n>=5?'Too many attempts. This account is locked.':'Email or password is incorrect.';}
  else{$b=db()->prepare('SELECT branch_id FROM branch_assignments WHERE employee_id=? AND end_date IS NULL ORDER BY start_date DESC LIMIT 1');$b->execute([$u['employee_id']]);$branch=$b->fetchColumn();if($u['role_name']==='Employee'&&!$branch){$error='Your account has no active branch assignment. Ask an administrator.';}else{session_regenerate_id(true);$_SESSION['admin_user']=['id'=>(int)$u['user_id'],'employee_id'=>(int)$u['employee_id'],'name'=>$u['full_name'],'role'=>$u['role_name'],'branch_id'=>$branch?(int)$branch:null];db()->prepare('UPDATE users SET failed_login_attempts=0,last_login_at=NOW() WHERE user_id=?')->execute([$u['user_id']]);audit('STAFF_LOGIN','users',(int)$u['user_id'],'Staff logged in');go('dashboard.php');}}
 }catch(Throwable $ex){$error='Could not connect to bankease. Verify config.php and database import.';}
}
page_start('Staff login');?><section class="login-card"><div class="eyebrow">Internal staff access</div><h1>BankEase Staff Portal</h1><p class="muted">Sign in with your employee account.</p><?php if($error):?><div class="notice err"><?=e($error)?></div><?php endif;?><form method="post"><?=csrf()?><div class="field"><label>Email</label><input name="email" type="email" required autocomplete="username"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password"></div><button class="button yellow">Log in</button></form><p class="muted">Customer website: <a href="http://localhost/BankEase_Fresh/">BankEase</a></p></section><?php page_end();
